from src.observability.pii_redaction import PIIType, detect_pii
class TestDetectPII:
    def test_detect_nric(self): text = 'Customer: John Doe, NRIC: S1234567A'; matches = detect_pii(text); nric_matches = [m for m in matches if m.pii_type == PIIType.NRIC]; assert len(nric_matches) == 1; assert nric_matches[0].original == 'S1234567A'; _m1_text = 'S1234567A G9876543Z T0123456B F7654321X M1111111A'; _m1_matches = detect_pii(_m1_text); _m1_nric_matches = [_m1_m for _m1_m in _m1_matches if _m1_m.pii_type == PIIType.NRIC]; assert len(_m1_nric_matches) == 5; _m2_text = 'Contact: user@example.com for support'; _m2_matches = detect_pii(_m2_text); _m2_email_matches = [_m2_m for _m2_m in _m2_matches if _m2_m.pii_type == PIIType.EMAIL]; assert len(_m2_email_matches) == 1; assert _m2_email_matches[0].original == 'user@example.com'; _m3_text = 'Call +65 91234567 or 65 81234567'; _m3_matches = detect_pii(_m3_text); _m3_phone_matches = [_m3_m for _m3_m in _m3_matches if _m3_m.pii_type == PIIType.PHONE]; assert len(_m3_phone_matches) >= 1; _m4_text = 'Mobile: 91234567'; _m4_matches = detect_pii(_m4_text); _m4_phone_matches = [_m4_m for _m4_m in _m4_matches if _m4_m.pii_type == PIIType.PHONE]; assert len(_m4_phone_matches) == 1; _m5_text = 'Address: 123 Main St, Singapore 518000'; _m5_matches = detect_pii(_m5_text); _m5_postal_matches = [_m5_m for _m5_m in _m5_matches if _m5_m.pii_type == PIIType.POSTAL_CODE]; assert len(_m5_postal_matches) == 1; assert _m5_postal_matches[0].original == '518000'; _m6_text = 'Account: 1234567890'; _m6_matches = detect_pii(_m6_text); _m6_account_matches = [_m6_m for _m6_m in _m6_matches if _m6_m.pii_type == PIIType.BANK_ACCOUNT]; assert len(_m6_account_matches) == 1; _m7_text = 'Date: 20250115'; _m7_matches = detect_pii(_m7_text); _m7_account_matches = [_m7_m for _m7_m in _m7_matches if _m7_m.pii_type == PIIType.BANK_ACCOUNT]; assert len(_m7_account_matches) == 0; _m8_text = 'Transaction: SALARY DEPOSIT 5000.00 SGD'; _m8_matches = detect_pii(_m8_text); _m8_sensitive_matches = [_m8_m for _m8_m in _m8_matches if _m8_m.pii_type in (PIIType.NRIC, PIIType.EMAIL)]; assert len(_m8_sensitive_matches) == 0; assert detect_pii('') == []
